2. High-Performance Symplectic Integrator in C++
Standard integrators like Forward Euler or standard Runge-Kutta 4th order (RK4) do not conserve the symplectic 2-form \(\omega = \sum dq_i \wedge dp_i\). Over long integration times, non-symplectic integrators suffer from artificial energy drift.
Below is a production-grade implementation of the Velocity Verlet (Symplectic Störmer-Verlet) algorithm in C++17:
// verlet_integrator.cpp
// Compile: g++ -O3 -std=c++17 verlet_integrator.cpp -o verlet_sim
#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;cmath&gt;
#include &lt;fstream&gt;
#include &lt;iomanip&gt;

struct State {
    double theta; // generalized coordinate
    double omega; // generalized velocity
    double t;
};

class SymplecticPendulum {
private:
    double g;
    double L;
    double m;

public:
    SymplecticPendulum(double gravity = 9.80665, double length = 1.0, double mass = 1.0)
        : g(gravity), L(length), m(mass) {}

    // Acceleration a(theta) = - (g / L) * sin(theta)
    double acceleration(double theta) const {
        return -(g / L) * std::sin(theta);
    }

    double totalEnergy(double theta, double omega) const {
        double kinetic = 0.5 * m * (L * omega) * (L * omega);
        double potential = m * g * L * (1.0 - std::cos(theta));
        return kinetic + potential;
    }

    // Velocity Verlet Step
    void step(State& s, double dt) const {
        double a_current = acceleration(s.theta);

        // 1. Position update: q(t + dt) = q(t) + v(t)*dt + 0.5*a(t)*dt^2
        s.theta += s.omega * dt + 0.5 * a_current * dt * dt;

        // 2. New acceleration: a(t + dt)
        double a_next = acceleration(s.theta);

        // 3. Velocity update: v(t + dt) = v(t) + 0.5*(a(t) + a(t + dt))*dt
        s.omega += 0.5 * (a_current + a_next) * dt;
        s.t += dt;
    }
};

int main() {
    SymplecticPendulum sim(9.80665, 1.0, 1.0);
    State state = {M_PI / 3.0, 0.0, 0.0}; // 60 degrees release from rest
    double dt = 0.005;
    double t_max = 50.0;

    std::ofstream out("verlet_trajectory.csv");
    out &lt;&lt; "time,theta,omega,energy\n";

    double E0 = sim.totalEnergy(state.theta, state.omega);

    while (state.t &lt;= t_max) {
        double E = sim.totalEnergy(state.theta, state.omega);
        out &lt;&lt; std::fixed &lt;&lt; std::setprecision(6)
            &lt;&lt; state.t &lt;&lt; "," &lt;&lt; state.theta &lt;&lt; "," &lt;&lt; state.omega &lt;&lt; "," &lt;&lt; E &lt;&lt; "\n";
        sim.step(state, dt);
    }

    std::cout &lt;&lt; "Simulation complete. Initial Energy: " &lt;&lt; E0 
              &lt;&lt; " J | Final Energy: " &lt;&lt; sim.totalEnergy(state.theta, state.omega) 
              &lt;&lt; " J (Symplectic bound preserved)." &lt;&lt; std::endl;
    return 0;
}

This section provides Python animation scripts using the Manim Community Engine (originally created by Grant Sanderson / 3Blue1Brown) to animate mathematical physics theorems, coordinate transformations, phase space portraits, and Lagrangian dynamics.



The double pendulum is the quintessential demonstration of sensitive dependence on initial conditions (Hamiltonian chaos). Below is the complete Manim Python script used to render the motion and overlay the Lagrangian:
#| file: pendulum_scene.py
from manim import *
import numpy as np

class DoublePendulumScene(Scene):
    def construct(self):
        title = Title("Double Pendulum: Hamiltonian Chaos", color=BLUE_B)
        self.play(Write(title))

        # Origin pivot
        origin = UP * 1.5
        pivot = Dot(origin, color=WHITE, radius=0.08)

        # Pendulum parameters
        l1, l2 = 2.0, 1.8
        theta1, theta2 = 120 * DEGREES, -45 * DEGREES

        # Calculate coordinates
        p1 = origin + l1 * np.array([np.sin(theta1), -np.cos(theta1), 0])
        p2 = p1 + l2 * np.array([np.sin(theta2), -np.cos(theta2), 0])

        rod1 = Line(origin, p1, color=GRAY_B, stroke_width=4)
        rod2 = Line(p1, p2, color=GRAY_B, stroke_width=4)

        bob1 = Dot(p1, color=RED, radius=0.15)
        bob2 = Dot(p2, color=YELLOW, radius=0.15)

        self.play(FadeIn(pivot), Create(rod1), Create(rod2), GrowFromCenter(bob1), GrowFromCenter(bob2))
        self.wait(1)

        # Equations overlay
        lagrangian = MathTex(
            r"\mathcal{L} = \frac{1}{2}(m_1+m_2)l_1^2\dot{\theta}_1^2 + \frac{1}{2}m_2 l_2^2\dot{\theta}_2^2 + m_2 l_1 l_2 \dot{\theta}_1\dot{\theta}_2 \cos(\theta_1-\theta_2) - V(\theta_1, \theta_2)",
            font_size=28
        ).to_edge(DOWN)

        self.play(Write(lagrangian))
        self.wait(2)


To render this scene with the Manim CLI:
# Preview in low quality (480p 15fps) for rapid iteration:
manim -pql simulations/pendulum_scene.py DoublePendulumScene

# Render final production video in 1080p 60fps:
manim -pqh simulations/pendulum_scene.py DoublePendulumScene

# Render in 4K resolution (2160p 60fps):
manim -pqk simulations/pendulum_scene.py DoublePendulumScene





